do $$
declare tenant uuid:=gen_random_uuid();admin_uuid uuid:=gen_random_uuid();school_user uuid:=gen_random_uuid();school uuid:=gen_random_uuid();event_uuid uuid:=gen_random_uuid();sport uuid:=gen_random_uuid();category uuid:=gen_random_uuid();person uuid:=gen_random_uuid();adult uuid:=gen_random_uuid();guardian_person uuid:=gen_random_uuid();part uuid;registration uuid;policy jsonb;payload jsonb;valid_data jsonb:='{"guardian_name":"Maria de Oliveira","guardian_cpf":"11144477735","guardian_relationship":"Mãe","guardian_phone":"(95) 99999-8888"}';result jsonb;issues jsonb;v bigint;cloned uuid;denied boolean;
begin
 begin
 insert into auth.users(id) values(admin_uuid),(school_user);
 insert into public.institutions(id,name,slug) values(tenant,'Responsável legal','guardian-'||tenant);
 insert into public.institution_memberships(institution_id,user_id,role,status) values(tenant,admin_uuid,'admin','approved');
 insert into public.schools(id,institution_id,name) values(school,tenant,'Escola');
 insert into public.events(id,institution_id,name,status) values(event_uuid,tenant,'Evento','open');
 insert into public.event_modalities(id,institution_id,event_id,name,classification) values(sport,tenant,event_uuid,'Atletismo','individual');
 insert into public.event_categories(id,institution_id,event_id,modality_id,name,participation) values(category,tenant,event_uuid,sport,'Categoria','individual');
 insert into public.people(id,institution_id,full_name,birth_date,cpf,gender) values(person,tenant,'Menor','2008-11-17','52998224725','Feminino'),(adult,tenant,'Maior','2008-11-16','12345678909','Masculino'),(guardian_person,tenant,'Responsável escolar','1990-01-01','11144477735','Feminino');
 insert into public.school_people(institution_id,school_id,person_id,role,status,user_id) values(tenant,school,person,'athlete','approved',null),(tenant,school,adult,'athlete','approved',null),(tenant,school,guardian_person,'responsible','approved',school_user);
 perform set_config('request.jwt.claim.sub',school_user::text,true);
 execute 'set local role authenticated';
 result:=public.siep_save_participation(event_uuid,school,person,array[category],'{}',true);part:=(result->>'id')::uuid;
 execute 'reset role';
 policy:='{"enabled":true,"referenceDate":"2026-11-16","fields":{"guardian_name":"required","guardian_cpf":"required","guardian_relationship":"required","guardian_phone":"required","guardian_email":"optional"}}';
 payload:=jsonb_build_object('fields','[]'::jsonb,'documents','[]'::jsonb,'guardian',policy);
 select configuration_version into v from public.events where id=event_uuid;
 perform set_config('request.jwt.claim.sub',school_user::text,true);
 execute 'set local role authenticated';
 denied:=false;begin perform public.siep_save_event_configuration(event_uuid,v,'requirements',payload);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Escola configurou exigência';end if;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',admin_uuid::text,true);
 execute 'set local role authenticated';
 v:=public.siep_save_event_configuration(event_uuid,v,'requirements',payload);
 execute 'reset role';
 issues:=siep_private.participation_issues(part);
 if not issues ? 'field_required:guardian_name' or not issues ? 'field_required:guardian_cpf' then raise exception 'Cadastro antigo não foi reavaliado: %',issues;end if;
 if siep_private.guardian_issues(event_uuid,adult,'{}')<>'[]' then raise exception 'Maior de idade teve exigência';end if;
 perform set_config('request.jwt.claim.sub',school_user::text,true);
 execute 'set local role authenticated';
 result:=public.siep_save_participation(event_uuid,school,adult,array[category],'{}',true);
 if result->>'status'<>'complete' then raise exception 'Adulto não concluiu sem responsável';end if;
 execute 'reset role';
 update public.people set birth_date='2008-02-29' where id=person;
 update public.events set settings=jsonb_set(settings,'{guardian,referenceDate}','"2026-02-28"') where id=event_uuid;
 if siep_private.guardian_issues(event_uuid,person,'{}')<>'[]' then raise exception 'Aniversário bissexto divergente';end if;
 update public.events set settings=jsonb_set(settings,'{guardian,referenceDate}','"2026-02-27"') where id=event_uuid;
 if siep_private.guardian_issues(event_uuid,person,'{}')='[]' then raise exception 'Menor bissexto não foi exigido';end if;
 update public.people set birth_date='2008-11-17' where id=person;
 update public.events set settings=jsonb_set(settings,'{guardian,referenceDate}','"2026-11-16"') where id=event_uuid;
 if siep_private.guardian_issues(event_uuid,person,valid_data)<>'[]' then raise exception 'Responsável válido recusado';end if;
 if not siep_private.guardian_issues(event_uuid,person,valid_data||'{"guardian_name":{}}') ? 'guardian_invalid:guardian_name' then raise exception 'Objeto aceito como nome';end if;
 update public.events set settings=jsonb_set(settings,'{guardian,enabled}','false') where id=event_uuid;
 if siep_private.guardian_issues(event_uuid,person,'{}')<>'[]' then raise exception 'Configuração desativada exigiu responsável';end if;
 update public.events set settings=jsonb_set(settings,'{guardian,enabled}','true') where id=event_uuid;
 if not siep_private.guardian_issues(event_uuid,person,valid_data||'{"guardian_cpf":"52998224725"}') ? 'guardian_invalid:guardian_cpf' then raise exception 'CPF do próprio atleta aceito';end if;
 if not siep_private.guardian_issues(event_uuid,person,valid_data||'{"guardian_email":"invalido"}') ? 'guardian_invalid:guardian_email' then raise exception 'Email opcional inválido aceito';end if;
 if not siep_private.guardian_issues(event_uuid,person,valid_data||'{"guardian_phone":"1"}') ? 'guardian_invalid:guardian_phone' then raise exception 'Telefone inválido aceito';end if;
 denied:=false;begin update public.events set settings=jsonb_set(settings,'{guardian,referenceDate}','"2026-02-30"') where id=event_uuid;exception when check_violation then denied:=true;end;if not denied then raise exception 'Data inválida aceita';end if;
 perform set_config('request.jwt.claim.sub',school_user::text,true);
 execute 'set local role authenticated';
 result:=public.siep_save_participation(event_uuid,school,person,array[category],'{}',false);
 denied:=false;begin perform public.siep_save_participation(event_uuid,school,person,array[category],'{}',true);exception when check_violation then denied:=true;end;if not denied then raise exception 'Concluiu sem responsável';end if;
 result:=public.siep_save_registration(event_uuid,school,category,null,jsonb_build_array(jsonb_build_object('participation_id',part,'slot_number',1)),'[]');registration:=(result->>'id')::uuid;
 denied:=false;begin perform public.siep_transition_registration(registration,1,'submitted','Enviar');exception when check_violation then denied:=true;end;if not denied then raise exception 'Enviou sem responsável';end if;
 perform public.siep_save_participation(event_uuid,school,person,array[category],valid_data,true);
 perform public.siep_transition_registration(registration,1,'submitted','Enviar');
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',admin_uuid::text,true);
 execute 'set local role authenticated';
 perform public.siep_transition_registration(registration,2,'approved','Conferido');
 cloned:=public.siep_duplicate_event(event_uuid,'Cópia','2027');
 execute 'reset role';
 if (select settings#>>'{guardian,enabled}' from public.events where id=cloned)<>'false' or (select settings#>>'{guardian,referenceDate}' from public.events where id=cloned)<>'' then raise exception 'Cópia herdou data de idade indevida';end if;
 if not exists(select 1 from public.registration_versions where registration_id=registration and status='approved' and snapshot#>>'{athletes,0,participation,additional_data,guardian_name}'='Maria de Oliveira') then raise exception 'Snapshot perdeu responsável';end if;
 if exists(select 1 from public.people where id=person and contact ? 'guardian_name') then raise exception 'Responsável foi para identidade global';end if;
 if has_function_privilege('authenticated','siep_private.guardian_issues(uuid,uuid,jsonb)','execute') then raise exception 'Helper privado exposto';end if;
 raise exception 'rollback_guardian_requirements' using errcode='ZX001';
 exception when sqlstate 'ZX001' then null;
 end;
end $$;
